mapper.select:
SELECT e.id, e.`name`, e.`location`, e.start_date, e.end_date, e.sort, e.country, e.country_name, e.exhibition_type, e.create_time
FROM exhibition_detail e

  AND e.`name` LIKE CONCAT('%', #{q.name}, '%')
  AND e.exhibition_type = #{q.type}
  AND YEAR(e.start_date) = #{q.year}

    AND e.country IN (SELECT a.id FROM global_area a WHERE a.continent_name = #{q.continent})

  AND e.country = #{q.country}
  AND e.end_date >= #{today}

ORDER BY e.end_date < #{today},
         CASE WHEN e.end_date >= #{today} THEN e.start_date END,
         e.start_date DESC, e.sort, e.id
